/* The port posts these to postmail (via composer_mail.queue_mail) as condition_type + condition.
   `repeat` has no postmail field yet: the port must add recurrence there (re-arm on fire). */
function toCondition(w){switch(w.kind){case"at":return["time",{run_at:w.at,repeat:w.repeat||"once"}];case"after":return["worker_done",{worker_id:w.id,when:w.on||"completed"}];
  case"file":return["file_change",{path:w.path}];case"ledger":return["ledger_message",{track:w.track}];
  case"allowance":return["allowance_return",{provider:w.provider,min_left_pct:w.min}];case"tokens":return["token_warning",{threshold_pct:w.pct}];}return[null,null];}
window.subwayQueue={items:()=>st.queue.map(q=>({...q,condition:toCondition(q.when)}))};

/* runs: one per lane. Lanes run side by side; each drains its own Up next when it goes idle. */
const busy=lane=>!!runs[lane];
const laneOf=()=>st.target&&st.target.kind==="chat"?st.target.id:"here";
function describe(lane){if(lane!=="here")return`Delivered to ${lane} · fm_${Math.random().toString(16).slice(2,6)}`;const p=prov(),m=model();
  return`Queued worker_${Math.random().toString(16).slice(2,8)} on ${p.label} · ${m.name}${st.effort?`, effort ${st.effort}`:m.efforts===null?", no effort sent":""}${st.station==="here"?": approve it in the HUD.":` on ${stationName()}: their "Start workers" setting decides whether it waits for their approval.`}`;}
function startRun(lane,msg,dur){dur=dur||(lane==="here"?3200:5200);
  runs[lane]={t0:performance.now(),dur,timer:setTimeout(()=>finish(lane,msg),dur)};
  if(lane==="here"){st.responding=true;live.textContent="Sending.";}renderAll();tickProg();}
function finish(lane,msg){delete runs[lane];if(lane==="here")st.responding=false;if(msg){showResult(msg);live.textContent=msg;}renderAll();drain(lane);}
function interrupt(lane){const r=runs[lane];if(!r)return;clearTimeout(r.timer);delete runs[lane];if(lane==="here")st.responding=false;}
const nextOf=lane=>st.queue.findIndex(q=>q.lane===lane&&q.when.kind==="next");
function drain(lane){if(busy(lane)||st.paused.has(lane)||nextOf(lane)<0)return;
  setTimeout(()=>{if(busy(lane)||st.paused.has(lane))return;const j=nextOf(lane);if(j<0)return;const[q]=st.queue.splice(j,1);saveQ();startRun(lane,describe(lane));},450);}
let progRaf=0;
function tickProg(){if(progRaf)return;const f=()=>{progRaf=0;
  queueEl.querySelectorAll("[data-prog]").forEach(b=>{const r=runs[b.dataset.prog],p=r?Math.min(1,(performance.now()-r.t0)/r.dur):0;b.style.transform=`scaleX(${p})`;b.style.opacity=r&&!st.paused.has(b.dataset.prog)?1:0;});
  if(Object.keys(runs).length)progRaf=requestAnimationFrame(f);};progRaf=requestAnimationFrame(f);}

function enqueue(text,lane,when){const q={id:newId(),text,lane,when:when&&when.kind!=="now"?when:{kind:"next"}};st.queue.push(q);saveQ();
  if(st.tab!=="all"&&st.tab!==lane)st.tab="all";
  if(q.when.kind!=="next"&&window.toast)toast.success("Scheduled",{description:`${text.split("\n")[0].slice(0,56)} · ${whenLabel(q.when)}`});
  live.textContent=q.when.kind==="next"?`Queued for ${laneLabel(lane)}, position ${st.queue.filter(x=>x.lane===lane&&x.when.kind==="next").length}.`:`Scheduled: ${whenLabel(q.when)}.`;
  renderAll();drain(lane);return q;}
function removeQ(q){st.queue=st.queue.filter(x=>x.id!==q.id);saveQ();renderAll();}
